/// every feature hook slot of this crate and the crates below, with whether it is filled
pub fn feature_hook_slots() -> Vec<(&'static str, bool)> {
    fn state<T>(slot: &'static crate::core::feature_hooks::feature_hooks::FeatureHookSlot<T>) -> (&'static str, bool) {
        (slot.name(), slot.is_installed())
    }
    let mut slots: Vec<(&'static str, bool)> = Vec::new();
    slots.extend(riseonly_ui_low::feature_hook_slots());
    slots.push(state(&crate::modules::chat::components::chat::backdrop::chat_wallpaper_sheet_hooks::CHAT_WALLPAPER_SHEET_HOOKS));
    slots.push(state(&crate::modules::chat::components::chat::bubble::message_content_hooks::MESSAGE_CONTENT_HOOKS));
    slots.push(state(&crate::modules::chat::components::chat::bubble::message_content_member_tag_hooks::MESSAGE_CONTENT_MEMBER_TAG_HOOKS));
    slots.push(state(&crate::modules::chat::components::chat_item::chat_context_preview_hooks::CHAT_CONTEXT_PREVIEW_HOOKS));
    slots.push(state(&crate::modules::chat::components::folders::account_state_reset_chat_folders_hooks::ACCOUNT_STATE_RESET_CHAT_FOLDERS_HOOKS));
    slots.push(state(&crate::modules::comment::widgets::comment_input_hooks::COMMENT_INPUT_HOOKS));
    slots
}
